    "difficulty": "Média",
    "statement": "Leia o texto para responder às questões de 09 a 12.\n\nEl mundo para algunos turistas no se acaba en \nla superficie de la Tierra. Los viajes al espacio y a las \nprofundidades de los océanos son una tendencia minoritaria, \npero al alza en el llamado turismo de élite. Están reservados \npara los pocos que pueden pagarlos y que, además, están \ndispuestos a aceptar algunos riesgos, como se ha puesto de \nmanifiesto en la desaparición el 18 de junio de 2023 de un \nsubmarino que llevaba a cuatro turistas a explorar los restos \ndel Titanic a 3.800 metros bajo el Atlántico. Son viajes que \nestán en la cima de la exclusividad en el creciente turismo de \nexperiencias, donde priman las sensaciones y que cada vez \nestá más de moda.\n\nSegún OceanGate, observar de primera mano los \nrestos del emblemático Titanic es una oportunidad para \nsalir de la vida cotidiana y descubrir algo verdaderamente \nextraordinario. “Llama la atención que el Titanic siga \nfascinando y creando tanto misterio”, opina José Serrano, \nprofesor de la Universidad Europea de Canarias y experto en \nturismo. El viajero busca experiencias “para lograr una meta \ny presumir de ello, mostrar lo que ha conseguido”. A partir de \nahí, depende del presupuesto: “El viaje es un básico en el \nque el común de los mortales puede elegir entre alguna que \notra alternativa y los que tienen mucho dinero disfrutan de un \ncatálogo cada vez más ilimitado”, añade.\n\nEn este mercado de las experiencias, el turismo \nsubmarino emerge como una nueva categoría y vende, en \nmuchos casos, autenticidad, algo único o de carácter local; \npuede ser para gente de más o menos presupuesto, y una \nparte es para una élite.\n\nLa gente con elevado presupuesto no se conforma con \ntomar una guía de viajes y elegir un par de rutas. Buscan \nexperiencias únicas y elegidas por especialistas que conocen \nlas últimas tendencias.\n\n(www.elpais.com.uy. Adaptado.)\n\nPor lo dicho en el texto,",
