    "statement": "Leia o texto para responder às questões 09 e 10.\n\nAlthough often used interchangeably by the general \npublic, there are crucial distinctions between the terms \n“refugee” and “migrant”:\n\nRefugee\n\nRefugees are persons who are outside their country of \norigin for reasons of feared persecution, conflict, generalized \nviolence, or other circumstances that have seriously disturbed \npublic order and, as a result, require international protection. \nThe refugee definition can be found in the 1951 Convention \nand regional refugee instruments, as well as United Nations \nCommissioner for Refugees’ (UNHCR) Statute.\n\nMigrant\n\nWhile there is no formal legal definition of an international \nmigrant, most experts agree that an international migrant is \nsomeone who changes his or her country of usual residence, \nindependently of the reason for migration or legal status. \nGenerally, a distinction is made between short-term or \ntemporary migration, covering movements with a duration \nbetween three and 12 months, and long-term or permanent \nmigration, referring to a change of country of residence for a \nduration of one year or more.\n\n(https://refugeesmigrants.un.org. Adaptado.)\n\nNo trecho inicial do texto “Although often used interchangeably \nby the general public”, o termo sublinhado equivale, em \nportuguês, a",
