    "statement": "O agronegócio brasileiro é responsável por mais de um \nterço das exportações da balança comercial. Estima-se que, \na cada R$ 3,00 gerados na economia nacional, R$ 1,00 \nvenha da agroindústria. Além disso, o setor é responsável \npor gerar 37% dos empregos criados. Esse desempenho \ncoloca o país em perspectiva de na próxima década ser o \nmaior produtor de commodities como farelo de soja, cana de \naçúcar, café e outros produtos da pecuária.\n\nÉ fato que o crescimento econômico proporciona uma \nmelhoria nas condições sociais de um país. Mas precisamos avaliar também a que custos. Além do desmatamento, \na expansão do agronegócio na Amazônia desperta outras \npreocupações que precisam e devem ser consideradas, tais \ncomo: aumento da pressão sobre a biodiversidade, aquecimento global, diminuição das áreas preservadas e, mais \nrecentemente, até a segurança alimentar.\n\n(https://portalamazonia.com. Adaptado.)\n\nA respeito do agronegócio na Amazônia, o excerto defende, \npara a região,",
